{"security_risk": "LOW", "summary": "Extract handbook text and search for key compliance terms", "command": "python - <<'PY'
from pypdf import PdfReader
from pathlib import Path
import re
pdf=Path('/app/data/handbook.pdf')
r=PdfReader(str(pdf))
texts=[]
for i,p in enumerate(r.pages):
    t=p.extract_text() or ''
    if t.strip():
        texts.append((i+1,t))
print('pages:',len(r.pages),'pages with text:',len(texts))
# build combined text with page markers
all_text='\n'.join([f"\n---PAGE {n}---\n{t}" for n,t in texts])
print('total chars',len(all_text))

def find_snippets(pattern, flags=re.I, ctx=300, max_hits=8):
    hits=[]
    for m in re.finditer(pattern, all_text, flags):
        start=max(0,m.start()-ctx)
        end=min(len(all_text),m.end()+ctx)
        hits.append(all_text[start:end])
        if len(hits)>=max_hits:
            break
    return hits

for pat in [r'preheat',r'ramp',r'liquidus',r'time\s+above\s+liquidus|TAL',r'peak',r'conveyor',r'speed\s*\(cm/min\)|cm/min']:
    snips=find_snippets(pat)
    print('\n=== pattern:',pat,'hits',len(snips),'===')
    for s in snips[:3]:
        print(s.replace('\n',' ')[:800])
PY"}

{"security_risk": "LOW", "summary": "Locate page numbers containing preheat ramp limit text", "command": "python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
for i,p in enumerate(r.pages, start=1):
    t=p.extract_text() or ''
    if re.search(r'preheat section', t, re.I):
        print('PAGE',i)
        # print relevant paragraph
        for m in re.finditer(r'(A typical profile.*?)(?:\n\n|$)', t, re.I|re.S):
            s=m.group(1)
            if 'preheat' in s.lower():
                print(s.replace('\n',' '))
                print('---')
PY"}

{"security_risk": "LOW", "summary": "Search handbook for peak temperature and 20C margin guidance", "command": "python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
for i,p in enumerate(r.pages, start=1):
    t=p.extract_text() or ''
    if re.search(r'exceed', t, re.I) and re.search(r'20', t):
        if re.search(r'melting', t, re.I) or re.search(r'peak', t, re.I):
            print('PAGE',i)
            # print lines containing 20 and exceed
            for line in t.splitlines():
                if re.search(r'20\s*', line) and re.search(r'ex', line, re.I):
                    print(line)
            print('--- excerpt ---')
            # show small excerpt around 'ex-' or 'exceeded'
            m=re.search(r'(This temperature.*?)(?:\n\n|$)', t, re.I|re.S)
            if m:
                print(m.group(1).replace('\n',' '))
PY"}

{"security_risk": "LOW", "summary": "Search handbook for peak temperature maximum/minimum requirements", "command": "python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
patterns=[r'peak',r'maximum\s+temperature',r'overheat',r'damage',r'\bmax\b.*temperature']
for pat in patterns:
    found=[]
    for i,p in enumerate(r.pages, start=1):
        t=p.extract_text() or ''
        if re.search(pat,t,re.I):
            found.append(i)
    print(pat,'pages',found)

# print any line with 'maximum temperature' or 'peak'
for i,p in enumerate(r.pages, start=1):
    t=p.extract_text() or ''
    if re.search(r'maximum\s+temperature|peak\s+temperature',t,re.I):
        print('\nPAGE',i)
        for line in t.splitlines():
            if re.search(r'maximum\s+temperature|peak\s+temperature',line,re.I):
                print(line)
PY"}

{"security_risk": "LOW", "summary": "Display handbook excerpts for damage and overheat mentions", "command": "python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
for page in [7,12]:
    t=r.pages[page-1].extract_text() or ''
    print('\n--- PAGE',page,'---')
    # print around keyword
    for kw in ['damage','overheat']:
        for m in re.finditer(kw,t,re.I):
            start=max(0,m.start()-300)
            end=min(len(t),m.end()+300)
            print(t[start:end].replace('\n',' '))
PY"}

{"security_risk": "LOW", "summary": "Search handbook for conveyor speed and dwell time guidance", "command": "python - <<'PY'
from pypdf import PdfReader
import re
r=PdfReader('/app/data/handbook.pdf')
keys=['conveyor speed','process speed','dwell','in/min','cm/min','time in oven','belt speed']
for i,p in enumerate(r.pages, start=1):
    t=p.extract_text() or ''
    if any(re.search(k,t,re.I) for k in keys):
        print('\nPAGE',i)
        # print lines containing keywords
        for line in t.splitlines():
            if any(re.search(k,line,re.I) for k in keys):
                print(line)
PY"}

