{"security_risk": "LOW", "summary": "Extract handbook text and search for key compliance terms", "command": "python - <<'PY'
from pypdf import PdfReader
from pathlib import Path
import re
pdf=Path('/app/data/handbook.pdf')
r=PdfReader(str(pdf))
texts=[]
for i,p in enumerate(r.pages):
    t=p.extract_text() or ''
    if t.strip():
        texts.append((i+1,t))
print('pages:',len(r.pages),'pages with text:',len(texts))
# build combined text with page markers
all_text='\n'.join([f"\n---PAGE {n}---\n{t}" for n,t in texts])
print('total chars',len(all_text))

def find_snippets(pattern, flags=re.I, ctx=300, max_hits=8):
    hits=[]
    for m in re.finditer(pattern, all_text, flags):
        start=max(0,m.start()-ctx)
        end=min(len(all_text),m.end()+ctx)
        hits.append(all_text[start:end])
        if len(hits)>=max_hits:
            break
    return hits

for pat in [r'preheat',r'ramp',r'liquidus',r'time\s+above\s+liquidus|TAL',r'peak',r'conveyor',r'speed\s*\(cm/min\)|cm/min']:
    snips=find_snippets(pat)
    print('\n=== pattern:',pat,'hits',len(snips),'===')
    for s in snips[:3]:
        print(s.replace('\n',' ')[:800])
